Table entry: TCP 192.168.1.20:51000 <-> 203.0.113.5:40001 -> 198.51.100.7:443

struct map {
    uint32_t in_ip;  uint16_t in_port;
    uint16_t out_port; uint8_t proto; time_t last_seen;
};
static struct map tbl[65536];  /* indexed by out_port */

uint16_t nat_out(uint8_t proto, uint32_t ip, uint16_t port) {
    for (int p = 1024; p < 65536; p++) {
        struct map *m = &tbl[p];
        if (m->out_port == p && m->proto == proto &&
            m->in_ip == ip && m->in_port == port) {
            m->last_seen = time(NULL);
            return p;                  /* existing mapping */
        }
    }
    for (int p = 1024; p < 65536; p++)
        if (tbl[p].out_port == 0) {    /* free slot */
            tbl[p] = (struct map){ip, port, p, proto, time(NULL)};
            return p;
        }
    return 0;                          /* ports exhausted */
}
